import pandas as pd

def find_first_day_of_max_degree(weather: pd.DataFrame) -> pd.DataFrame:
    if weather.empty:
        return pd.DataFrame({'city_id': [], 'day': [], 'degree': []})
    sorted_df = weather.sort_values(['city_id', 'degree', 'day'], ascending=[True, False, True])
    res = sorted_df.drop_duplicates(subset=['city_id'], keep='first')
    return res[['city_id', 'day', 'degree']]
